def mse(predictions, actuals):
    return sum((p - a) ** 2 for p, a in zip(predictions, actuals)) / len(actuals)

print(mse([1.0, 2.0], [1.0, 4.0]))

errors = {'underfit': (2.9, 3.1), 'good': (0.6, 0.7), 'overfit': (0.0, 1.8)}
best = min(errors, key=lambda name: errors[name][1])
print(best)
